// Status presentation reads computed ability bonuses without mutating native stacks.
function effectiveEnemyStatus(e,key){const r=S.run;if(key==='str'&&e.act2&&r)return snowStrength(r,e);if(key==='agility'&&e.snowKey==='ice'&&r&&snowMate(r,e))return (e.agility||0)+(r.curse||0);return e[key]||0;}
keywords.呪い付与量='行動で付与する呪いの量に加算する。屍噛には適用されない。';
keywords.凍結付与量='行動で付与する凍結の量に加算する。';
function afflictionBonuses(e){return {curseBonus:(e.curseBonus||0)+(e.snowKey==='corpseDragon'?(e.dragonBonus||0)+(e.selfInflictBonus||0):0),freezeBonus:(e.freezeBonus||0)+(e.snowKey==='ice'?(e.dragonBonus||0)+(e.selfInflictBonus||0):0)};}
const feedbackEnemyStatusBase=enemyStatusHTML;enemyStatusHTML=function(e){let html=feedbackEnemyStatusBase(e),bonuses=afflictionBonuses(e);let extra='';if(bonuses.curseBonus)extra+=statusEffectHTML('呪い付与量',bonuses.curseBonus);if(bonuses.freezeBonus)extra+=statusEffectHTML('凍結付与量',bonuses.freezeBonus);return html.replace('<div class="player-status enemy-status-list">','<div class="player-status enemy-status-list">'+extra);};
const STATUS_FEEDBACK={str:['筋力','↑'],agility:['守護','◇'],block:['ブロック','⬡'],poison:['毒','☠'],plate:['プレート','▣'],regen:['再生','✚'],thorns:['棘','✦'],freeze:['凍結','❄'],curse:['呪い','☽'],armorStrike:['甲撃','⚒'],laceration:['裂傷','†'],vulnerable:['脆弱','◈'],curseBonus:['呪い付与量','☽'],freezeBonus:['凍結付与量','❄'],tracking:['追跡','◎'],bleedBonus:['残虐','†'],evolutionBlock:['過程','⬡'],evolutionStrength:['成長','↑'],retainBlock:['ブロック維持','⬡'],bloodBlessing:['血の恵み','♥'],burn:['焼身','♨'],rage:['激昂','↑'],thornShield:['茨の盾','✦'],thornGarden:['茨の園','✦'],forge:['鍛え直し','⚒'],exhaustStrength:['灰の肉体','↑'],exhaustEngine:['除外時ブロック','⬡'],poisonAura:['毒の波動','☠'],poisonCoat:['毒の刃','☠'],passion:['情熱','♥'],heartbeat:['鼓動','♥'],hunterStun:['スタン','⏸'],damageReduction:['軽減','◇'],territory:['縄張り','◈'],beastHunt:['獣の狩り','†'],bleedRepeat:['腐食','†'],evolutionDiscount:['進化コスト軽減','◈']};
let statusFeedbackRun=null,statusFeedbackState=new WeakMap(),statusFeedbackLanes=new WeakMap();
function statusValues(unit,r){const out={};for(const key of Object.keys(STATUS_FEEDBACK))out[key]=key==='str'||key==='agility'?unit===r?(unit[key]||0):effectiveEnemyStatus(unit,key):Number(unit[key])||0;if(unit!==r)Object.assign(out,afflictionBonuses(unit));return out;}
let statusVisualSeed=(Date.now()>>>0)||1;
function statusVisualRandom(){statusVisualSeed^=statusVisualSeed<<13;statusVisualSeed^=statusVisualSeed>>>17;statusVisualSeed^=statusVisualSeed<<5;return (statusVisualSeed>>>0)/4294967296;}
function statusNoticePoint(unit,rect){const now=Date.now(),old=statusFeedbackLanes.get(unit),points=old&&now-old.time<180?old.points:[];let best=null,bestDistance=-1;for(let i=0;i<16;i++){const candidate={x:rect.left+rect.width*(.15+statusVisualRandom()*.7),y:rect.top+rect.height*(.15+statusVisualRandom()*.55)},distance=points.length?Math.min(...points.map(p=>Math.hypot(candidate.x-p.x,candidate.y-p.y))):Infinity;if(distance>bestDistance){best=candidate;bestDistance=distance;}if(distance>=22)break;}statusFeedbackLanes.set(unit,{time:now,points:[...points,best].slice(-8)});return best;}
function recordStatusGain(unit,key,amount){if(globalThis.ASHBOUND_HEADLESS||!amount||page!=='battle'||typeof document.createElement!=='function'||typeof document.body.append!=='function')return;const r=S.run,entity=unit===r?'player':r?.enemies?.indexOf(unit);if(entity==null||entity===-1)return;const portrait=document.querySelector('[data-entity="'+entity+'"] .portrait');if(!portrait?.getBoundingClientRect)return;const rect=portrait.getBoundingClientRect(),[name,icon]=STATUS_FEEDBACK[key];const label=document.createElement('span');label.className='status-gain-float';const percent=key==='damageReduction'||key==='territory',point=statusNoticePoint(unit,rect);label.textContent=icon+' '+name+' '+(amount>0?'+':'')+(percent?Math.round(amount*100)+'%':amount);label.style.left=point.x+'px';label.style.top=point.y+'px';label.setAttribute('aria-hidden','true');document.body.append(label);setTimeout(()=>label.remove(),1550);}
function syncStatusFeedback(silent=false){const r=S.run;if(!r||page!=='battle'){statusFeedbackRun=null;statusFeedbackState=new WeakMap();return;}if(statusFeedbackRun!==r){statusFeedbackRun=r;statusFeedbackState=new WeakMap();}for(const unit of [r,...(r.enemies||[])]){const next=statusValues(unit,r),previous=statusFeedbackState.get(unit)||{};statusFeedbackState.set(unit,next);if(!silent&&unit.hp>0)for(const key of Object.keys(next))if(next[key]>(previous[key]||0))recordStatusGain(unit,key,next[key]-(previous[key]||0));else if((key==='str'||key==='agility')&&next[key]<0&&next[key]<(previous[key]||0))recordStatusGain(unit,key,next[key]-(previous[key]||0));}}
// Observe at synchronous effect boundaries, including nested damage/counter effects.
function withStatusFeedback(fn){return function(...args){syncStatusFeedback();try{return fn.apply(this,args);}finally{syncStatusFeedback();}};}
gainBlock=withStatusFeedback(gainBlock);addVulnerable=withStatusFeedback(addVulnerable);addLaceration=withStatusFeedback(addLaceration);addPoison=withStatusFeedback(addPoison);applyCurse=withStatusFeedback(applyCurse);releaseCurse=withStatusFeedback(releaseCurse);loseHP=withStatusFeedback(loseHP);dealDamage=withStatusFeedback(dealDamage);planSnow=withStatusFeedback(planSnow);snowAction=withStatusFeedback(snowAction);triggerBattleCall=withStatusFeedback(triggerBattleCall);exhaustCard=withStatusFeedback(exhaustCard);resolveHunterEffects=withStatusFeedback(resolveHunterEffects);onCardResolved=withStatusFeedback(onCardResolved);applyTurnStartBuffs=withStatusFeedback(applyTurnStartBuffs);hunterEnemyActionEnd=withStatusFeedback(hunterEnemyActionEnd);hunterPlayerTurnEnd=withStatusFeedback(hunterPlayerTurnEnd);base.play=withStatusFeedback(base.play);
// Hand instances are presentation-only. Matching duplicate IDs never changes deck data.
let handViewRun=null,handViewTurn=null,handViewCards=[],handViewSerial=0;
function handLayout(count,width,cardWidth,gap=15){count=Math.min(10,Math.max(0,count));if(!count)return {stride:0,start:0};const stride=count>6?Math.max(1,Math.min(cardWidth+gap,(width-cardWidth)/Math.max(1,count-1))):cardWidth+gap;return {stride,start:Math.max(0,(width-(cardWidth+(count-1)*stride))/2)};}
function captureHandView(){if(page!=='battle'||S.run!==handViewRun||S.run?.turn!==handViewTurn)return new Map();const result=new Map();document.querySelectorAll('.hand > .card-wrap').forEach((el,i)=>{const entry=handViewCards[i];if(entry&&el.getBoundingClientRect)result.set(entry.token,el.getBoundingClientRect());});return result;}
function fitHand(){if(page!=='battle'||!S.run||globalThis.ASHBOUND_HEADLESS)return;const hand=document.querySelector('.cards.hand');if(!hand)return;const children=[...hand.querySelectorAll(':scope > .card-wrap')],overlap=children.length>6 || (window.matchMedia?.('(min-width: 850px)').matches && children.length * (children[0]?.querySelector('.card')?.offsetWidth || 0) > hand.clientWidth);children.forEach((el,i)=>{
  const angle = (i - (children.length - 1) / 2) * Math.min(6, 36 / Math.max(1, children.length - 1));
  el.style.setProperty('--hand-angle', angle + 'deg');
  el.style.setProperty('--hand-drop', Math.abs(angle) * 1.7 + 'px');
  el.style.order=i;el.style.zIndex=i+1;
});hand.classList.toggle('is-overlapping',overlap);if(!overlap){hand.style.height='';for(const el of children){el.style.left='';el.style.top='';el.style.width='';el.style.zIndex='';}return;}const first=children[0]?.querySelector('.card'),width=first?.offsetWidth||166,available=hand.clientWidth||width*6,layout=handLayout(children.length,available,width);let height=0;children.forEach((el,i)=>{el.style.width=width+'px';el.style.left=layout.start+i*layout.stride+'px';el.style.top='0px';el.style.zIndex=i+1;height=Math.max(height,el.offsetHeight||first?.offsetHeight||245);});hand.style.height=height+'px';}
function handEntryMotion(entry,now){const start=entry.enterAt||now,elapsed=Math.max(0,now-start),progress=Math.min(1,elapsed/440),frames=[{opacity:Math.min(1,progress/.42),transform:'translateY('+(-26*(1-progress))+'px)',offset:0}];if(progress<.42)frames.push({opacity:1,transform:'translateY(-16px)',offset:(.42-progress)/(1-progress)});frames.push({opacity:1,transform:'translateY(0)',offset:1});return {frames,options:{duration:Math.max(1,440-elapsed),delay:Math.max(0,start-now),fill:'backwards',easing:'cubic-bezier(.2,.7,.3,1)'}};}
function animateHandView(previous){if(globalThis.ASHBOUND_HEADLESS)return;const r=S.run;if(page!=='battle'||!r){handViewRun=null;handViewTurn=null;handViewCards=[];return;}const old=handViewRun===r&&handViewTurn===r.turn?handViewCards:[],pools=new Map();for(const item of old){if(!pools.has(item.id))pools.set(item.id,[]);pools.get(item.id).push(item);}const now=Date.now();let enterAt=Math.max(now,...old.map(c=>(c.enterAt||0)+120));handViewCards=r.hand.map(id=>{const previous=pools.get(id)?.shift();if(previous)return previous;const entry={id,token:++handViewSerial,enterAt};enterAt+=120;return entry;});handViewRun=r;handViewTurn=r.turn;fitHand();const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;document.querySelectorAll('.hand > .card-wrap').forEach((el,i)=>{if(!el.animate)return;const entry=handViewCards[i];if(!entry)return;const oldRect=previous.get(entry.token),rect=el.getBoundingClientRect(),scale=el.offsetWidth?rect.width/el.offsetWidth:1;if(reduced)return;if(oldRect&&(!entry.enterAt||now>=entry.enterAt+440)){const x=(oldRect.left-rect.left)/(scale||1),y=(oldRect.top-rect.top)/(scale||1);if(Math.abs(x)+Math.abs(y)>.5)el.animate([{transform:'translate('+x+'px,'+y+'px)'},{transform:'translate(0,0)'}],{duration:240,easing:'cubic-bezier(.2,.7,.3,1)'});}else{const motion=handEntryMotion(entry,now);el.animate(motion.frames,motion.options);}});}

const frontEvolutionBase=showEvolutionPreview;showEvolutionPreview=function(wrap){frontEvolutionBase(wrap);const node=document.getElementById('evolution-preview'),dialog=wrap.closest?.('dialog[open]');if(node&&dialog)dialog.append(node);};
const frontInspectBase=inspectExplorerCard;inspectExplorerCard=function(...args){frontInspectBase(...args);wireEvolutionPreviews();wireCardHelpPortals();};
let cardHelpSource=null;
function hideCardHelpPortal(){document.getElementById('card-keyword-portal')?.remove?.();cardHelpSource?.classList?.remove('portal-help-active');cardHelpSource=null;}
function showCardHelpPortal(wrap){hideCardHelpPortal();if(drag||typeof document.createElement!=='function')return;const tip=wrap.querySelector(':scope > .tooltip'),source=wrap.querySelector('.card');if(!tip||!source?.getBoundingClientRect||!document.body.append)return;const portal=document.createElement('aside');portal.id='card-keyword-portal';portal.className='tooltip card-help-portal';portal.setAttribute('role','tooltip');portal.innerHTML=tip.innerHTML;(source.closest?.('dialog[open]')||document.body).append(portal);cardHelpSource=wrap;wrap.classList.add('portal-help-active');const rect=source.getBoundingClientRect(),width=portal.offsetWidth||235,height=portal.offsetHeight||200;const fitsRight=rect.right+12+width<=window.innerWidth;let left=fitsRight?rect.right+12:rect.left-width-12,top=(rect.bottom??rect.top+rect.height)-height;const evolution=document.getElementById('evolution-preview');if(!fitsRight&&evolution)left=rect.left-(evolution.offsetWidth||166)-24-width;portal.style.left=Math.max(8,Math.min(left,window.innerWidth-width-8))+'px';portal.style.top=Math.max(8,Math.min(top,window.innerHeight-height-8))+'px';}
function wireCardHelpPortals(){if(globalThis.ASHBOUND_HEADLESS)return;document.querySelectorAll('.card-wrap').forEach(wrap=>{if(!wrap.querySelector(':scope > .tooltip')||wrap.dataset?.helpPortalBound)return;if(wrap.dataset)wrap.dataset.helpPortalBound='1';for(const [event,action] of [['onmouseenter',()=>showCardHelpPortal(wrap)],['onmouseleave',hideCardHelpPortal],['onfocusin',()=>showCardHelpPortal(wrap)],['onfocusout',hideCardHelpPortal]]){const previous=wrap[event];wrap[event]=function(e){previous?.call(this,e);action();};}});}
function recordHealEvent(unit,amount){if(globalThis.ASHBOUND_HEADLESS||amount<=0||typeof document.createElement!=='function'||!document.body.append)return;const r=S.run,key=unit===r?'player':r?.enemies?.indexOf(unit);if(key==null||key===-1)return;const source=document.querySelector('[data-entity="'+key+'"] .portrait')||(unit===r?document.querySelector('.header-hp'):null);if(!source?.getBoundingClientRect)return;const rect=source.getBoundingClientRect(),label=document.createElement('b');label.className='damage-float healing-event';label.textContent='+'+amount;label.style.left=rect.left+rect.width/2+'px';label.style.top=rect.top+rect.height*.3+'px';document.body.append(label);setTimeout(()=>label.remove(),1150);}
